
alter table public.commercial_leads add column if not exists catalog_request jsonb;
grant insert(catalog_request) on public.commercial_leads to authenticated;
alter table public.commercial_leads add constraint catalog_snapshot_object check (catalog_request is null or (jsonb_typeof(catalog_request)='object' and catalog_request->>'version'='1'));
alter table public.commercial_messages drop constraint commercial_messages_body_check;
alter table public.commercial_messages add constraint commercial_messages_body_check check(length(body) between 1 and 12000);
create or replace function public.validate_commercial_catalog() returns trigger language plpgsql security invoker set search_path='' as $$
declare
 catalog constant jsonb := '[{"id":"landing-page-basica","category":"Sites","name":"Landing page básica","price_cents":40000,"deadline":"3 dias úteis","scope":"Uma página com até 4 blocos e botão de contato.","monthly":false,"website":true},{"id":"landing-page-profissional","category":"Sites","name":"Landing page profissional","price_cents":60000,"deadline":"5 dias úteis","scope":"Uma página com até 7 blocos, formulário e WhatsApp.","monthly":false,"website":true},{"id":"landing-page-premium","category":"Sites","name":"Landing page premium","price_cents":80000,"deadline":"7 dias úteis","scope":"Até 10 blocos, animações e medição básica de ações.","monthly":false,"website":true},{"id":"portfolio-profissional","category":"Sites","name":"Portfólio profissional","price_cents":60000,"deadline":"5 dias úteis","scope":"Até 4 páginas e 10 projetos.","monthly":false,"website":true},{"id":"site-institucional","category":"Sites","name":"Site institucional","price_cents":90000,"deadline":"7 dias úteis","scope":"Até 3 páginas, contato, mapa e redes sociais.","monthly":false,"website":true},{"id":"site-empresarial-completo","category":"Sites","name":"Site empresarial completo","price_cents":140000,"deadline":"10 dias úteis","scope":"Até 5 páginas, formulário e SEO básico.","monthly":false,"website":true},{"id":"site-premium-personalizado","category":"Sites","name":"Site premium personalizado","price_cents":180000,"deadline":"15 dias úteis","scope":"Até 7 páginas e animações leves.","monthly":false,"website":true},{"id":"site-com-painel-administrativo","category":"Sites","name":"Site com painel administrativo","price_cents":200000,"deadline":"15 dias úteis","scope":"Até 5 páginas e edição de uma categoria de conteúdo.","monthly":false,"website":true},{"id":"reformulacao-de-site","category":"Sites","name":"Reformulação de site","price_cents":70000,"deadline":"7 dias úteis","scope":"Reformulação de até 3 páginas.","monthly":false,"website":true},{"id":"cardapio-digital-em-pdf","category":"Cardápios","name":"Cardápio digital em PDF","price_cents":25000,"deadline":"3 dias úteis","scope":"Até 4 páginas e 40 itens.","monthly":false,"website":false},{"id":"cardapio-digital-profissional","category":"Cardápios","name":"Cardápio digital profissional","price_cents":45000,"deadline":"5 dias úteis","scope":"Até 50 itens, categorias e QR Code.","monthly":false,"website":true},{"id":"site-institucional-com-cardapio","category":"Cardápios","name":"Site institucional com cardápio","price_cents":100000,"deadline":"8 dias úteis","scope":"Até 3 páginas e cardápio de 50 itens.","monthly":false,"website":true},{"id":"site-completo-com-sistema-de-pedidos","category":"Cardápios","name":"Site completo com sistema de pedidos","price_cents":200000,"deadline":"12 dias úteis","scope":"Até 50 itens, carrinho e pedido via WhatsApp.","monthly":false,"website":true},{"id":"catalogo-digital","category":"Lojas virtuais","name":"Catálogo digital","price_cents":50000,"deadline":"5 dias úteis","scope":"Até 30 produtos, sem checkout.","monthly":false,"website":true},{"id":"loja-com-pedidos-via-whatsapp","category":"Lojas virtuais","name":"Loja com pedidos via WhatsApp","price_cents":100000,"deadline":"8 dias úteis","scope":"Até 40 produtos, carrinho e pedido via WhatsApp.","monthly":false,"website":true},{"id":"loja-virtual-completa","category":"Lojas virtuais","name":"Loja virtual completa","price_cents":200000,"deadline":"15 dias úteis","scope":"Até 50 produtos, checkout e painel padrão.","monthly":false,"website":true},{"id":"e-commerce-avancado","category":"Lojas virtuais","name":"E-commerce avançado","price_cents":300000,"deadline":"20 dias úteis","scope":"Até 100 produtos, 1 integração e painel padrão.","monthly":false,"website":true},{"id":"scripts-personalizados","category":"Sistemas e automações","name":"Scripts personalizados","price_cents":25000,"deadline":"3 dias úteis","scope":"Um script para uma tarefa.","monthly":false,"website":false},{"id":"bots-personalizados","category":"Sistemas e automações","name":"Bots personalizados","price_cents":45000,"deadline":"5 dias úteis","scope":"Um bot com até 5 comandos.","monthly":false,"website":false},{"id":"automacao-de-processos","category":"Sistemas e automações","name":"Automação de processos","price_cents":60000,"deadline":"7 dias úteis","scope":"Um fluxo com até 3 etapas e 1 serviço externo.","monthly":false,"website":false},{"id":"integracao-de-sistemas-e-apis","category":"Sistemas e automações","name":"Integração de sistemas e APIs","price_cents":70000,"deadline":"8 dias úteis","scope":"2 serviços, até 3 operações.","monthly":false,"website":false},{"id":"painel-administrativo","category":"Sistemas e automações","name":"Painel administrativo","price_cents":120000,"deadline":"10 dias úteis","scope":"Até 3 telas e gestão de um tipo de registro.","monthly":false,"website":false},{"id":"sistema-empresarial-inicial","category":"Sistemas e automações","name":"Sistema empresarial inicial","price_cents":350000,"deadline":"25 dias úteis","scope":"Login, até 3 módulos simples e 1 perfil.","monthly":false,"website":false},{"id":"integracao-com-inteligencia-artificial","category":"Sistemas e automações","name":"Integração com inteligência artificial","price_cents":120000,"deadline":"10 dias úteis","scope":"Um recurso de IA via API em sistema existente.","monthly":false,"website":false},{"id":"configuracao-de-campanhas","category":"Tráfego pago","name":"Configuração de campanhas","price_cents":30000,"deadline":"3 dias úteis","scope":"Uma plataforma e uma campanha.","monthly":false,"website":false},{"id":"meta-ads","category":"Tráfego pago","name":"Meta Ads","price_cents":60000,"deadline":"30 dias corridos","scope":"Até 2 campanhas e relatório mensal.","monthly":true,"website":false},{"id":"google-ads","category":"Tráfego pago","name":"Google Ads","price_cents":70000,"deadline":"30 dias corridos","scope":"Até 2 campanhas e relatório mensal.","monthly":true,"website":false},{"id":"meta-ads-google-ads","category":"Tráfego pago","name":"Meta Ads + Google Ads","price_cents":100000,"deadline":"30 dias corridos","scope":"Até 2 campanhas por plataforma.","monthly":true,"website":false},{"id":"gestao-avancada-de-trafego","category":"Tráfego pago","name":"Gestão avançada de tráfego","price_cents":150000,"deadline":"30 dias corridos","scope":"Até 6 campanhas, testes e acompanhamento semanal.","monthly":true,"website":false},{"id":"manutencao-mensal-opcional","category":"Suporte","name":"Manutenção mensal opcional","price_cents":15000,"deadline":"Mensal","scope":"Até 1 hora de pequenos ajustes.","monthly":true,"website":false},{"id":"atualizacao-mensal-de-cardapio","category":"Suporte","name":"Atualização mensal de cardápio","price_cents":8000,"deadline":"Mensal","scope":"Até 15 alterações de itens ou preços.","monthly":true,"website":false},{"id":"pagina-adicional","category":"Suporte","name":"Página adicional","price_cents":20000,"deadline":"3 dias úteis","scope":"Uma página de até 5 seções.","monthly":false,"website":false},{"id":"correcoes-e-melhorias","category":"Suporte","name":"Correções e melhorias","price_cents":25000,"deadline":"3 dias úteis","scope":"Um chamado de até 2 horas.","monthly":false,"website":false},{"id":"otimizacao-para-buscas-seo","category":"Suporte","name":"Otimização para buscas (SEO)","price_cents":35000,"deadline":"5 dias úteis","scope":"SEO técnico de até 5 páginas.","monthly":false,"website":false},{"id":"otimizacao-de-desempenho","category":"Suporte","name":"Otimização de desempenho","price_cents":30000,"deadline":"5 dias úteis","scope":"Ajustes em até 5 páginas.","monthly":false,"website":false},{"id":"integracoes-adicionais","category":"Suporte","name":"Integrações adicionais","price_cents":40000,"deadline":"5 dias úteis","scope":"Uma integração simples.","monthly":false,"website":false}]'::jsonb;
 choice jsonb; offer jsonb; selection jsonb := '[]'::jsonb; seen text[] := '{}';
 selected_id text; maint text; base int; extra int; once_total int := 0; month_total int := 0; has_site boolean := false;
begin
 if new.catalog_request is null then
  if new.service='Catálogo comercial' then raise exception 'Catalog choices required' using errcode='23514'; end if;
  return new;
 end if;
 if jsonb_typeof(new.catalog_request)<>'array' then raise exception 'Invalid catalog selection' using errcode='23514'; end if;
 if jsonb_array_length(new.catalog_request) not between 1 and jsonb_array_length(catalog) then raise exception 'Invalid selection count' using errcode='23514'; end if;
 for choice in select value from jsonb_array_elements(new.catalog_request) loop
  selected_id:=choice->>'id'; maint:=choice->>'maintenance';
  if selected_id is null or selected_id=any(seen) then raise exception 'Invalid or duplicate service' using errcode='23514'; end if;
  select value into offer from jsonb_array_elements(catalog) where value->>'id'=selected_id;
  if offer is null then raise exception 'Unknown catalog service' using errcode='23514'; end if;
  seen:=array_append(seen,selected_id);
  if (offer->>'website')::boolean then
   has_site:=true;
   if maint is null or maint not in ('yes','no') then raise exception 'Choose monthly maintenance for each website' using errcode='23514'; end if;
  elsif maint is not null then raise exception 'Invalid maintenance selection' using errcode='23514'; end if;
  base:=(offer->>'price_cents')::int; extra:=case when maint='yes' then 15000 else 0 end;
  if (offer->>'monthly')::boolean then month_total:=month_total+base; else once_total:=once_total+base; end if;
  month_total:=month_total+extra;
  selection:=selection||jsonb_build_array(offer||jsonb_build_object('maintenance',maint,'maintenance_cents',extra));
 end loop;
 if has_site and 'manutencao-mensal-opcional'=any(seen) then raise exception 'Use the per-site maintenance choice' using errcode='23514'; end if;
 new.catalog_request:=jsonb_build_object('version',1,'items',selection,'one_time_cents',once_total,'monthly_cents',month_total);
 new.service:='Catálogo comercial';
 return new;
end; $$;
revoke execute on function public.validate_commercial_catalog() from public,anon,authenticated;
create trigger validate_commercial_catalog_before before insert on public.commercial_leads for each row execute function public.validate_commercial_catalog();
create or replace function public.post_catalog_chat_message() returns trigger language plpgsql security invoker set search_path='' as $$
declare item jsonb; summary text := E'Novo pedido pelo catálogo comercial\n\n'; 
begin
 if new.catalog_request is null then return new; end if;
 for item in select value from jsonb_array_elements(new.catalog_request->'items') loop
  summary:=summary||'• '||(item->>'name')||' — R$ '||replace(to_char((item->>'price_cents')::numeric/100,'FM999999990.00'),'.',',')||case when (item->>'monthly')::boolean then '/mês' else '' end||' · '||(item->>'deadline')||E'\n';
  if (item->>'website')::boolean then summary:=summary||'  Manutenção mensal: '||case when item->>'maintenance'='yes' then 'Sim — R$ 150,00/mês' else 'Não — R$ 0,00/mês' end||E'\n'; end if;
 end loop;
 summary:=summary||E'\nTotal único: R$ '||replace(to_char((new.catalog_request->>'one_time_cents')::numeric/100,'FM999999990.00'),'.',',')||E'\nTotal mensal: R$ '||replace(to_char((new.catalog_request->>'monthly_cents')::numeric/100,'FM999999990.00'),'.',',')||E'\n\nDescrição do projeto:\n'||new.message;
 insert into public.commercial_messages(lead_id,sender_id,sender_role,body) values(new.id,new.customer_id,'customer',summary);
 return new;
end; $$;
revoke execute on function public.post_catalog_chat_message() from public,anon,authenticated;
create trigger post_catalog_chat_message_after after insert on public.commercial_leads for each row execute function public.post_catalog_chat_message();
